  ];
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
   if (!$record) { continue; }
   $text = (string) $record->symbolism;
   $generated = str_starts_with($text,'Число '.$number.' можно использовать как повод для самонаблюдения.')
    || str_starts_with($text,'Иногда мы замечаем число в тот момент')
    || str_starts_with($text,'Представь это число не как указание судьбы')
    || str_starts_with($text,'Не нужно верить, что совпадение что-то предсказывает')
    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
}
